"use client";

import { useNews } from "@/hooks/useNews";
import { NewsUpdateBanner } from "@/components/news-update-banner";
import { NewsCardsGrid } from "@/components/news-cards-grid";

export function InvestmentRounds() {
  const { 
    articles: apiNews,
    hasUpdates,
    newCount,
    triggerUpdate,
    lastSyncRelative
  } = useNews('"Startup" OR "Venture Capital" OR "Fintech" OR "Rodada de investimento"', "Startups", 12);
  
  return (
    <>
      {lastSyncRelative && (
        <div className="mb-3 flex justify-end">
          <span className="text-[10px] text-muted-foreground font-semibold uppercase tracking-wider animate-pulse">
            Atualizado {lastSyncRelative}
          </span>
        </div>
      )}
      <div className="flex flex-col gap-4">
        {apiNews.length > 0 && (
          <div className="mt-2">
            <h2 className="text-xl font-bold font-heading text-foreground mb-4">Últimas Notícias do Setor</h2>
            <NewsCardsGrid news={apiNews} />
          </div>
        )}
      </div>
      <NewsUpdateBanner hasUpdates={hasUpdates} newCount={newCount} onUpdate={triggerUpdate} />
    </>
  );
}
